/bin/bash -lc "cat > app/Dashboard.tsx <<'EOF'
import { headers } from 'next/headers'

type ApiResult = { data: unknown; error?: never } | { data?: never; error: true }

async function fetchDashboardData(origin: string, path: string): Promise<ApiResult> {
  try {
    const response = await fetch(new URL(path, origin), { cache: 'no-store' })
    if ("'!response.ok) throw new Error('"'Request failed')

    return { data: await response.json() }
  } catch {
    return { error: true }
  }
}

export default async function Dashboard() {
  const requestHeaders = await headers()
  const host = requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host')

  if ("'!host) {
    return <p>Unable to load dashboard data.</p>
  }

  const protocol = requestHeaders.get('"'x-forwarded-proto') === 'https' ? 'https' : 'http'
  const origin = "'`${protocol}://${host}`
  const [analytics, notifications, settings] = await Promise.all([
    fetchDashboardData(origin, '"'/api/analytics'),
    fetchDashboardData(origin, '/api/notifications'),
    fetchDashboardData(origin, '/api/settings'),
  ])

  return (
    <div>
      <h2>Dashboard Content</h2>
      <section>
        <h3>Analytics</h3>
        {analytics.error ? <p>Unable to load analytics.</p> : <pre>{JSON.stringify(analytics.data, null, 2)}</pre>}
      </section>
      <section>
        <h3>Notifications</h3>
        {notifications.error ? <p>Unable to load notifications.</p> : <pre>{JSON.stringify(notifications.data, null, 2)}</pre>}
      </section>
      <section>
        <h3>Settings</h3>
        {settings.error ? <p>Unable to load settings.</p> : <pre>{JSON.stringify(settings.data, null, 2)}</pre>}
      </section>
    </div>
  )
}
EOF
